   "answer": 0,
   "explain": "】场所对应+动宾关系。金库是保管现金的场所，二者是场所对应。保管现金构成动 宾结构，二者是动宾关系。 A 项，美术馆是陈列字画的场所，二者是场所对应。陈列字画构成动宾结构，二者是动 宾关系，与题干逻辑关系一致，当选； B 项，录音棚是录制专辑的场所，而非播放专辑，与题干逻辑关系不一致，排除； C 项，网球场是观看比赛的场所，不是观看球迷，与题干逻辑关系不一致，排除； D 项，电缆车是交通工具，而非场所，与题干逻辑关系不一致，排除。 故正确答案为A。",
