   "module": "yanyu",
   "q": "同样是基于这种神秘的想象，欧洲人认为香料具有圣洁之气。在基督徒丧葬火化时，香味必须越浓越好。把香料涂抹在遗体上或者同遗体一起焚烧，有着赎罪的意涵。这段文字最适合放到文中哪一位置（ ）",
