   "q": "甲、乙两辆卡车运输一批货物，其中甲车每次能运输35 箱货物。甲车先满载运输2 次后，乙车加入并与甲车共同满载运输10 次完成任务，此时乙车比甲车多运输10 箱货物。问如果乙车单独执行整个运输任务且每次都尽量装满，最后一次运多少箱货物（ ）",
